// shapes_canvas.js paints a frame's shapes onto a browser canvas, for every
// canvas app. The shapes are lib/Shapes.roc's, which the platform declares as
// web/platform/Frame.roc's `Shape`; roc_glue.js, generated by `roc glue` from
// that type, reads them out of the wasm, and this file does what a canvas
// does with them. It answers one name, `ShapesCanvas`, with `paint`.
//
// Its Roc twin is safari/gates/ShapesPixels.roc, which paints the same shapes into
// exact pixels, with no anti-aliasing, for Safari's gate. The gate checks the
// twin, not this file, since Roc can't run a canvas. This file is checked by
// page_check.mjs, which runs every built page against a stand-in canvas, and
// by camera_check.mjs, which checks where a view mark puts points, and by
// text_check.mjs, which checks how a line of type is set.

const stopAt = (offset, floor = 0) => Math.max(floor, Math.min(1, offset));
const channel = (v) => Math.max(0, Math.min(255, Math.round(v)));
const cssColor = (c) => `rgba(${channel(c.r)},${channel(c.g)},${channel(c.b)},${c.a})`;

const withStops = (gradient, stops) => {
  stops.forEach(([offset, color]) => gradient.addColorStop(offset, color));
  return gradient;
};

// Brush.mix, operation for operation, so a colour's last bit agrees with lib's.
const mix = (p, q, t) => ({
  r: p.r + (q.r - p.r) * t, g: p.g + (q.g - p.g) * t,
  b: p.b + (q.b - p.b) * t, a: p.a + (q.a - p.a) * t,
});

// Brush's two_stop: the colour the stops give at t, for t in [0, 1].
const twoStopAt = (s, t) => t <= s.start_offset ? s.start_color
  : t >= s.end_offset ? s.end_color
  : mix(s.start_color, s.end_color, (t - s.start_offset) / (s.end_offset - s.start_offset));

// A canvas takes offsets in [0, 1] only. An offset past either end becomes a
// stop at that end in the colour Brush.shade gives there, so the gradient
// matches lib's mix across the whole of [0, 1].
const twoStops = (s) => [
  [stopAt(s.start_offset), cssColor(s.start_offset >= 0 ? s.start_color : twoStopAt(s, 0))],
  [stopAt(s.end_offset, stopAt(s.start_offset)), cssColor(s.end_offset <= 1 ? s.end_color : twoStopAt(s, 1))],
];

// Brush.mix and Brush's two_stop, for a gradient with no length. A canvas paints
// nothing there, and Brush.shade gives the colour at the far end, so this works
// that colour out as Brush.shade does, step for step.
const mix = (p, q, t) => ({ r: p.r + (q.r - p.r) * t, g: p.g + (q.g - p.g) * t, b: p.b + (q.b - p.b) * t, a: p.a + (q.a - p.a) * t });
const twoStopAt = (s, t) => (t <= s.start_offset ? s.start_color
  : t >= s.end_offset ? s.end_color
    : mix(s.start_color, s.end_color, (t - s.start_offset) / (s.end_offset - s.start_offset)));

// A fill becomes something canvas can paint with. An ellipse is the exception:
// it paints through a transform, so it stays a descriptor.
function paintFor(ctx, fill) {
  const p = fill.value;
  switch (fill.tag) {
    case "Flat":
      return cssColor(p);
    case "Span":
      // Brush.shade's t is 1 when the edges meet, all the way from the middle
      // colour to the edge colour.
      if (p.right_x === p.left_x) return cssColor(mix(p.middle_color, p.edge_color, 1));
      return withStops(ctx.createLinearGradient(p.left_x, 0, p.right_x, 0),
        [[0, cssColor(p.edge_color)], [0.5, cssColor(p.middle_color)], [1, cssColor(p.edge_color)]]);
    case "Radial":
      // With no ring to walk, Brush.shade mixes all the way to the outer colour.
      if (!(p.outer_radius > p.inner_radius)) return cssColor(mix(p.inner_color, p.outer_color, 1));
      return withStops(ctx.createRadialGradient(p.center.x, p.center.y, p.inner_radius, p.center.x, p.center.y, p.outer_radius),
        [[0, cssColor(p.inner_color)], [1, cssColor(p.outer_color)]]);
    case "Linear": {
      const dx = p.end_point.x - p.start_point.x;
      const dy = p.end_point.y - p.start_point.y;
      if (!(dx * dx + dy * dy > 0)) return cssColor(twoStopAt(p.stops, 1));
      return withStops(ctx.createLinearGradient(p.start_point.x, p.start_point.y, p.end_point.x, p.end_point.y),
        twoStops(p.stops));
    }
    case "Glow":
      // With no ring to walk, Brush.shade takes t = 1, past the middle offset,
      // and mixes from the middle colour to the outer one.
      if (!(p.outer_radius > p.inner_radius)) {
        return cssColor(mix(p.middle_color, p.outer_color, (1 - p.middle_offset) / (1 - p.middle_offset)));
      }
      return withStops(ctx.createRadialGradient(p.center.x, p.center.y, p.inner_radius, p.center.x, p.center.y, p.outer_radius),
        [[0, cssColor(p.inner_color)], [p.middle_offset, cssColor(p.middle_color)], [1, cssColor(p.outer_color)]]);
    case "Ellipse":
      return { ellipse: p };
    default:
      throw new Error(`shapes_canvas: no brush ${fill.tag}`);
  }
}

// An ellipse brush carries its axes, the matrix that takes the unit circle to
// the ellipse, which is the transform a canvas wants.
function fillThroughEllipse(ctx, p) {
  ctx.save();
  ctx.clip();
  ctx.transform(p.axis_u.x, p.axis_u.y, p.axis_v.x, p.axis_v.y, p.center.x, p.center.y);
  ctx.fillStyle = withStops(ctx.createRadialGradient(0, 0, 0, 0, 0, 1), twoStops(p.stops));
  ctx.fillRect(-1e4, -1e4, 2e4, 2e4); // clipped to the path; past r=1 the gradient holds
  ctx.restore();
}

function fillShape(ctx, fill) {
  const paint = paintFor(ctx, fill);
  if (paint.ellipse) fillThroughEllipse(ctx, paint.ellipse);
  else { ctx.fillStyle = paint; ctx.fill(); }
}

function tracePoly(ctx, coordinates) {
  ctx.beginPath();
  ctx.moveTo(coordinates[0], coordinates[1]);
  for (let i = 2; i < coordinates.length; i += 2) ctx.lineTo(coordinates[i], coordinates[i + 1]);
  ctx.closePath();
}

// Where the shapes after a view mark are: the camera written as the matrix a
// canvas takes. Camera.world_to_screen does this in Roc, BeginMode2D in raylib.
// `scale` is how many canvas pixels the app's own pixel takes.
function setSpace(ctx, space, scale) {
  if (space.tag === "Screen") { ctx.setTransform(scale, 0, 0, scale, 0, 0); return; }
  const c = space.value;
  const radians = (c.rotation * Math.PI) / 180;
  const cos = Math.cos(radians) * c.zoom;
  const sin = Math.sin(radians) * c.zoom;
  ctx.setTransform(scale * cos, scale * sin, -scale * sin, scale * cos,
    scale * (c.offset.x - (c.target.x * cos - c.target.y * sin)),
    scale * (c.offset.y - (c.target.x * sin + c.target.y * cos)));
}

// The viewer's own typefaces. A stack names the best face on each common system
// and ends in the generic family, so a page loads no font and always finds one.
const TYPEFACES = {
  Prose: 'system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
  Code: 'ui-monospace, SFMono-Regular, Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace',
};
const TEXT_ALIGN = { Left: 'left', Center: 'center' };

function paintText(ctx, p) {
  ctx.font = `${p.size}px ${TYPEFACES[p.face.tag]}`;
  ctx.textAlign = TEXT_ALIGN[p.align.tag];
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = cssColor(p.color);
  ctx.fillText(p.text, p.x, p.y);
}

const scratch = { canvas: null, ctx: null };

function paintImage(ctx, p) {
  if (!p.cols || !p.rows) return;
  if (!scratch.canvas) {
    scratch.canvas = document.createElement('canvas');
    scratch.ctx = scratch.canvas.getContext('2d');
  }
  if (scratch.canvas.width !== p.cols || scratch.canvas.height !== p.rows) {
    scratch.canvas.width = Number(p.cols);
    scratch.canvas.height = Number(p.rows);
  }
  const image = scratch.ctx.createImageData(Number(p.cols), Number(p.rows));
  const bytes = image.data;
  for (let i = 0; i < p.pixels.length; i++) {
    const c = p.pixels[i];
    bytes[i * 4] = channel(c.r);
    bytes[i * 4 + 1] = channel(c.g);
    bytes[i * 4 + 2] = channel(c.b);
    bytes[i * 4 + 3] = channel(c.a * 255);
  }
  scratch.ctx.putImageData(image, 0, 0);
  const smoothing = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(scratch.canvas, 0, 0, Number(p.cols), Number(p.rows), p.x, p.y, p.width, p.height);
  ctx.imageSmoothingEnabled = smoothing;
}

function paintFrame(ctx, shapes, scale = 1) {
  for (const shape of shapes) {
    const p = shape.value;
    switch (shape.tag) {
      // The two marks are not shapes: one says how the shapes after it
      // combine, the other says where they are.
      case "Blend":
        ctx.globalCompositeOperation = p.tag === "Add" ? 'lighter' : 'source-over';
        break;
      case "View":
        setSpace(ctx, p, scale);
        break;
      case "Image":
        paintImage(ctx, p);
        break;
      case "Text":
        paintText(ctx, p);
        break;
      case "Poly":
        tracePoly(ctx, p.coordinates);
        fillShape(ctx, p.fill);
        break;
      case "Rect":
        ctx.beginPath();
        ctx.rect(p.x, p.y, p.width, p.height);
        ctx.closePath();
        fillShape(ctx, p.fill);
        break;
      case "Disc":
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.closePath();
        fillShape(ctx, p.fill);
        break;
      default:
        throw new Error(`shapes_canvas: no shape ${shape.tag}`);
    }
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
}

const ShapesCanvas = { paint: paintFrame };
